[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>MedBook — Find and Book Top Doctors Instantly</title>
<link href="https://cdn.jsdelivr.net/npm/remixicon@4.6.0/fonts/remixicon.css" rel="stylesheet">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --navy:#1B1464;
  --yellow:#FFD930;
  --white:#FFFFFF;
  --gray-50:#F9FAFB;
  --gray-100:#F3F4F6;
  --gray-200:#E5E7EB;
  --gray-400:#9CA3AF;
  --gray-600:#4B5563;
  --gray-700:#374151;
  --gray-800:#1F2937;
  --navy-light:#2D24A0;
  --navy-lighter:#EDE9FE;
  --shadow-sm:0 1px 2px rgba(27,20,100,.06);
  --shadow-md:0 4px 16px rgba(27,20,100,.10);
  --shadow-lg:0 12px 40px rgba(27,20,100,.14);
  --radius-sm:8px;
  --radius-md:12px;
  --radius-lg:16px;
  --radius-xl:24px;
}
html{scroll-behavior:smooth}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;color:var(--gray-700);background:var(--white);line-height:1.6;-webkit-font-smoothing:antialiased}

/* ── HEADER ── */
.header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--gray-100);transition:box-shadow .3s}
.header.scrolled{box-shadow:var(--shadow-md)}
.header-inner{max-width:1200px;margin:0 auto;padding:0 24px;height:64px;display:flex;align-items:center;justify-content:space-between}
.logo{display:flex;align-items:center;gap:8px;text-decoration:none;font-weight:800;font-size:1.35rem;color:var(--navy)}
.logo i{font-size:1.6rem;color:var(--navy)}
.logo span{background:var(--yellow);padding:2px 6px;border-radius:4px;margin-left:2px}
.nav-links{display:flex;align-items:center;gap:8px}
.nav-links a{text-decoration:none;color:var(--gray-700);font-weight:500;font-size:.9rem;padding:8px 14px;border-radius:var(--radius-sm);transition:background .2s,color .2s}
.nav-links a:hover{background:var(--gray-100);color:var(--navy)}
.nav-links .btn-login{color:var(--navy)}
.nav-links .btn-signup{background:var(--navy);color:var(--white);padding:8px 20px}
.nav-links .btn-signup:hover{background:var(--navy-light)}
.hamburger{display:none;background:none;border:none;font-size:1.5rem;color:var(--navy);cursor:pointer;padding:8px}

/* Mobile Drawer */
.mobile-drawer{position:fixed;top:0;right:-300px;width:280px;height:100vh;background:var(--white);z-index:200;transition:right .3s ease;box-shadow:var(--shadow-lg);padding:24px;display:flex;flex-direction:column;gap:8px}
.mobile-drawer.open{right:0}
.drawer-overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:199;opacity:0;pointer-events:none;transition:opacity .3s}
.drawer-overlay.open{opacity:1;pointer-events:all}
.drawer-close{align-self:flex-end;background:none;border:none;font-size:1.5rem;color:var(--gray-600);cursor:pointer;padding:4px}
.mobile-drawer a{text-decoration:none;color:var(--gray-700);font-weight:500;font-size:1.05rem;padding:14px 16px;border-radius:var(--radius-sm);display:block;transition:background .2s}
.mobile-drawer a:hover{background:var(--gray-100)}
.mobile-drawer .drawer-signup{background:var(--navy);color:var(--white);text-align:center;margin-top:12px}
.mobile-drawer .drawer-signup:hover{background:var(--navy-light)}

/* ── HERO ── */
.hero{background:linear-gradient(165deg,var(--navy) 0%,var(--navy-light) 55%,#3B2FBF 100%);padding:80px 24px 100px;position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;top:-40%;right:-20%;width:600px;height:600px;border-radius:50%;background:rgba(255,217,48,.08);pointer-events:none}
.hero::after{content:'';position:absolute;bottom:-30%;left:-10%;width:400px;height:400px;border-radius:50%;background:rgba(255,255,255,.04);pointer-events:none}
.hero-inner{max-width:1200px;margin:0 auto;position:relative;z-index:1;text-align:center}
.hero h1{font-size:3.2rem;font-weight:800;color:var(--white);line-height:1.15;max-width:720px;margin:0 auto 16px}
.hero p{font-size:1.15rem;color:rgba(255,255,255,.82);max-width:600px;margin:0 auto 40px;line-height:1.7}

/* Search Bar */
.search-bar{max-width:820px;margin:0 auto;background:var(--white);border-radius:var(--radius-lg);padding:8px;box-shadow:var(--shadow-lg);display:flex;align-items:stretch;gap:4px;position:relative}
.search-field{flex:1;display:flex;align-items:center;gap:8px;padding:12px 16px;border-radius:var(--radius-md);position:relative;background:var(--gray-50);min-width:0}
.search-field i{color:var(--gray-400);font-size:1.15rem;flex-shrink:0}
.search-field input,.search-field select{border:none;outline:none;background:transparent;font-family:inherit;font-size:.95rem;color:var(--gray-800);width:100%}
.search-field select{cursor:pointer;-webkit-appearance:none;appearance:none}
.search-field select option{color:var(--gray-800)}
.search-divider{width:1px;background:var(--gray-200);align-self:stretch;margin:8px 0}
.search-btn{background:var(--yellow);color:var(--navy);border:none;font-family:inherit;font-weight:700;font-size:.95rem;padding:14px 32px;border-radius:var(--radius-md);cursor:pointer;display:flex;align-items:center;gap:8px;transition:background .2s,transform .1s;white-space:nowrap}
.search-btn:hover{background:#FFE455}
.search-btn:active{transform:scale(.97)}

/* Autocomplete Dropdown */
.autocomplete-dropdown{position:absolute;top:calc(100% + 6px);left:0;right:0;background:var(--white);border-radius:var(--radius-md);box-shadow:var(--shadow-lg);z-index:50;display:none;overflow:hidden;border:1px solid var(--gray-100)}
.autocomplete-dropdown.show{display:block}
.autocomplete-item{padding:12px 16px;cursor:pointer;display:flex;align-items:center;gap:10px;font-size:.9rem;color:var(--gray-700);transition:background .15s}
.autocomplete-item:hover,.autocomplete-item.active{background:var(--gray-50);color:var(--navy)}
.autocomplete-item i{color:var(--gray-400);font-size:1rem}
.autocomplete-item .highlight{font-weight:600;color:var(--navy)}

/* ── SPECIALTIES ── */
.specialties{padding:80px 24px;background:var(--white)}
.section-inner{max-width:1200px;margin:0 auto}
.section-label{display:inline-flex;align-items:center;gap:6px;font-size:.8rem;font-weight:600;text-transform:uppercase;letter-spacing:.08em;color:var(--navy);background:var(--navy-lighter);padding:6px 14px;border-radius:99px;margin-bottom:12px}
.section-title{font-size:2rem;font-weight:800;color:var(--navy);margin-bottom:8px}
.section-subtitle{font-size:1.05rem;color:var(--gray-600);max-width:540px;margin-bottom:40px}
.specialty-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.specialty-card{background:var(--white);border:1.5px solid var(--gray-200);border-radius:var(--radius-lg);padding:28px 24px;display:flex;align-items:flex-start;gap:16px;cursor:pointer;transition:border-color .25s,box-shadow .25s,transform .2s;text-decoration:none;color:inherit}
.specialty-card:hover{border-color:var(--navy);box-shadow:var(--shadow-md);transform:translateY(-3px)}
.specialty-icon{width:52px;height:52px;border-radius:var(--radius-md);display:flex;align-items:center;justify-content:center;font-size:1.5rem;flex-shrink:0;transition:transform .2s}
.specialty-card:hover .specialty-icon{transform:scale(1.08)}
.specialty-icon.primary{background:#E0E7FF;color:#4338CA}
.specialty-icon.dentist{background:#FEF3C7;color:#B45309}
.specialty-icon.derma{background:#FCE7F3;color:#BE185D}
.specialty-icon.psych{background:#EDE9FE;color:#6D28D9}
.specialty-icon.eye{background:#DBEAFE;color:#1D4ED8}
.specialty-icon.ortho{background:#D1FAE5;color:#047857}
.specialty-card h3{font-size:1.05rem;font-weight:700;color:var(--navy);margin-bottom:4px}
.specialty-card p{font-size:.85rem;color:var(--gray-600);line-height:1.5}

/* ── HOW IT WORKS ── */
.how-it-works{padding:80px 24px;background:var(--gray-50)}
.steps-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;position:relative}
.steps-grid::before{content:'';position:absolute;top:44px;left:calc(16.66% + 28px);right:calc(16.66% + 28px);height:2px;background:var(--gray-200);z-index:0}
.step{text-align:center;position:relative;z-index:1}
.step-number{width:56px;height:56px;border-radius:50%;background:var(--navy);color:var(--yellow);font-size:1.2rem;font-weight:800;display:flex;align-items:center;justify-content:center;margin:0 auto 20px;position:relative}
.step-number::after{content:'';position:absolute;inset:-4px;border-radius:50%;border:2px dashed var(--gray-200)}
.step h3{font-size:1.1rem;font-weight:700;color:var(--navy);margin-bottom:8px}
.step p{font-size:.9rem;color:var(--gray-600);line-height:1.65;max-width:280px;margin:0 auto}

/* ── STATS ── */
.stats{padding:56px 24px;background:var(--navy)}
.stats-inner{max-width:1200px;margin:0 auto;display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.stat-item{text-align:center}
.stat-value{font-size:2.2rem;font-weight:800;color:var(--yellow);line-height:1.2}
.stat-label{font-size:.9rem;color:rgba(255,255,255,.75);margin-top:6px;line-height:1.4}

/* ── TESTIMONIALS ── */
.testimonials{padding:80px 24px;background:var(--white)}
.testimonial-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.testimonial-card{background:var(--gray-50);border-radius:var(--radius-lg);padding:28px 24px;position:relative;border:1px solid var(--gray-100);transition:box-shadow .25s}
.testimonial-card:hover{box-shadow:var(--shadow-md)}
.testimonial-stars{display:flex;gap:2px;margin-bottom:14px}
.testimonial-stars i{color:var(--yellow);font-size:.95rem}
.testimonial-card blockquote{font-size:.92rem;color:var(--gray-700);line-height:1.7;margin-bottom:16px;font-style:italic}
.testimonial-author{font-size:.85rem;font-weight:600;color:var(--navy)}
.testimonial-location{font-size:.8rem;color:var(--gray-400);margin-top:2px}

/* ── APP PROMO ── */
.app-promo{padding:80px 24px;background:var(--gray-50)}
.app-inner{max-width:1200px;margin:0 auto;display:flex;align-items:center;gap:64px}
.app-content{flex:1}
.app-content .section-label{margin-bottom:12px}
.app-content h2{font-size:2rem;font-weight:800;color:var(--navy);margin-bottom:12px}
.app-content>p{font-size:1.05rem;color:var(--gray-600);line-height:1.7;margin-bottom:28px;max-width:460px}
.app-features{display:grid;grid-template-columns:1fr 1fr;gap:12px 24px;margin-bottom:32px}
.app-feature{display:flex;align-items:center;gap:10px;font-size:.9rem;color:var(--gray-700)}
.app-feature i{color:var(--navy);font-size:1.1rem}
.app-buttons{display:flex;gap:12px;flex-wrap:wrap}
.app-btn{display:inline-flex;align-items:center;gap:10px;padding:12px 24px;border-radius:var(--radius-md);text-decoration:none;font-weight:600;font-size:.9rem;transition:transform .2s,box-shadow .2s}
.app-btn:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}
.app-btn.ios{background:var(--navy);color:var(--white)}
.app-btn.android{background:var(--white);color:var(--navy);border:1.5px solid var(--gray-200)}
.app-visual{flex:0 0 320px;display:flex;justify-content:center;align-items:center}
.phone-mockup{width:240px;height:440px;background:var(--navy);border-radius:32px;position:relative;overflow:hidden;box-shadow:var(--shadow-lg);border:4px solid #2D24A0}
.phone-screen{position:absolute;inset:12px;background:var(--white);border-radius:24px;overflow:hidden;display:flex;flex-direction:column}
.phone-status{height:24px;background:var(--navy);display:flex;align-items:center;justify-content:center}
.phone-status span{width:48px;height:5px;border-radius:99px;background:rgba(255,255,255,.3)}
.phone-body{flex:1;padding:16px;display:flex;flex-direction:column;gap:8px}
.phone-body .mini-search{background:var(--gray-100);border-radius:8px;padding:8px 12px;font-size:.6rem;color:var(--gray-400)}
.phone-body .mini-card{background:var(--gray-50);border-radius:8px;padding:10px;display:flex;gap:8px;align-items:center}
.phone-body .mini-avatar{width:28px;height:28px;border-radius:50%;background:var(--navy-lighter)}
.phone-body .mini-text{flex:1}
.phone-body .mini-text span{display:block;height:4px;background:var(--gray-200);border-radius:2px;margin-bottom:4px}
.phone-body .mini-text span:last-child{width:60%;margin-bottom:0}
.phone-body .mini-btn{background:var(--yellow);color:var(--navy);border-radius:6px;padding:6px 0;text-align:center;font-size:.55rem;font-weight:700}

/* ── FOOTER ── */
.footer{background:var(--navy);padding:56px 24px 32px;color:rgba(255,255,255,.7)}
.footer-inner{max-width:1200px;margin:0 auto}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr 1fr;gap:32px;margin-bottom:48px}
.footer-brand .logo{color:var(--white);margin-bottom:14px}
.footer-brand .logo span{background:var(--yellow);color:var(--navy)}
.footer-brand p{font-size:.85rem;line-height:1.7;max-width:260px}
.footer-col h4{font-size:.8rem;font-weight:700;color:var(--white);text-transform:uppercase;letter-spacing:.08em;margin-bottom:14px}
.footer-col a{display:block;font-size:.85rem;color:rgba(255,255,255,.6);text-decoration:none;padding:4px 0;transition:color .2s}
.footer-col a:hover{color:var(--yellow)}
.footer-bottom{border-top:1px solid rgba(255,255,255,.12);padding-top:24px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px}
.footer-bottom p{font-size:.8rem}
.footer-social{display:flex;gap:12px}
.footer-social a{width:36px;height:36px;border-radius:50%;border:1px solid rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;color:rgba(255,255,255,.6);font-size:1rem;text-decoration:none;transition:border-color .2s,color .2s}
.footer-social a:hover{border-color:var(--yellow);color:var(--yellow)}

/* ── RESPONSIVE ── */
@media(max-width:1024px){
  .specialty-grid{grid-template-columns:repeat(2,1fr)}
  .testimonial-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1.4fr 1fr 1fr}
  .app-inner{gap:40px}
  .app-visual{flex:0 0 260px}
}
@media(max-width:768px){
  .nav-links{display:none}
  .hamburger{display:block}
  .hero h1{font-size:2.2rem}
  .hero p{font-size:1rem}
  .hero{padding:56px 24px 80px}
  .search-bar{flex-direction:column;gap:6px;padding:12px}
  .search-divider{width:100%;height:1px;margin:0}
  .search-btn{width:100%;justify-content:center;padding:14px}
  .specialties,.how-it-works,.testimonials,.app-promo{padding:56px 20px}
  .specialty-grid{grid-template-columns:1fr}
  .steps-grid{grid-template-columns:1fr;gap:40px}
  .steps-grid::before{display:none}
  .stats-inner{grid-template-columns:repeat(2,1fr);gap:20px}
  .stat-value{font-size:1.6rem}
  .testimonial-grid{grid-template-columns:1fr}
  .app-inner{flex-direction:column-reverse;gap:32px}
  .app-visual{flex:none}
  .app-features{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr 1fr}
  .footer-brand{grid-column:1/-1}
}
@media(max-width:480px){
  .hero h1{font-size:1.8rem}
  .section-title{font-size:1.5rem}
  .stats-inner{grid-template-columns:1fr 1fr}
  .footer-grid{grid-template-columns:1fr}
  .app-buttons{flex-direction:column}
  .app-btn{justify-content:center}
}
</style>
</head>
<body>

<!-- ── HEADER ── -->
<header class="header" id="header">
  <div class="header-inner">
    <a href="index.html" class="logo">
      <i class="ri-heart-pulse-line"></i>Med<span>Book</span>
    </a>
    <nav class="nav-links">
      <a href="#specialties">Browse</a>
      <a href="#">Help</a>
      <a href="#" class="btn-login">Log In</a>
      <a href="#" class="btn-signup">Sign Up</a>
    </nav>
    <button class="hamburger" id="hamburgerBtn" aria-label="Open menu">
      <i class="ri-menu-3-line"></i>
    </button>
  </div>
</header>

<!-- Mobile Drawer -->
<div class="drawer-overlay" id="drawerOverlay"></div>
<div class="mobile-drawer" id="mobileDrawer">
  <button class="drawer-close" id="drawerClose" aria-label="Close menu"><i class="ri-close-line"></i></button>
  <a href="#specialties">Browse</a>
  <a href="#">Help</a>
  <a href="#">Log In</a>
  <a href="#" class="drawer-signup">Sign Up</a>
</div>

<!-- ── HERO ── -->
<section class="hero">
  <div class="hero-inner">
    <h1>Find and book the care you need</h1>
    <p>Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.</p>
    <div class="search-bar" id="searchBar">
      <div class="search-field" style="flex:1.4">
        <i class="ri-search-line"></i>
        <input type="text" id="searchInput" placeholder="Search by condition, specialty, or doctor name" autocomplete="off">
      </div>
      <div class="search-divider"></div>
      <div class="search-field">
        <i class="ri-map-pin-line"></i>
        <input type="text" id="locationInput" placeholder="City, state, or zip code">
      </div>
      <div class="search-divider"></div>
      <div class="search-field" style="flex:0.7">
        <i class="ri-shield-check-line"></i>
        <select id="insuranceSelect">
          <option value="">Choose insurance</option>
          <option>Aetna</option>
          <option>Blue Cross Blue Shield</option>
          <option>Cigna</option>
          <option>UnitedHealthcare</option>
          <option>Humana</option>
          <option>Kaiser Permanente</option>
          <option>Anthem</option>
          <option>Molina Healthcare</option>
          <option>Oscar Health</option>
        </select>
      </div>
      <button class="search-btn" id="searchBtn">
        <i class="ri-search-line"></i>Search
      </button>
      <div class="autocomplete-dropdown" id="autocompleteDropdown"></div>
    </div>
  </div>
</section>

<!-- ── SPECIALTIES ── -->
<section class="specialties" id="specialties">
  <div class="section-inner">
    <span class="section-label"><i class="ri-stethoscope-line"></i> Specialties</span>
    <h2 class="section-title">Popular specialties</h2>
    <p class="section-subtitle">Browse top-rated providers by specialty and find the right care for you.</p>
    <div class="specialty-grid">
      <a href="#" class="specialty-card" data-specialty="Primary Care">
        <div class="specialty-icon primary"><i class="ri-stethoscope-line"></i></div>
        <div>
          <h3>Primary Care</h3>
          <p>Annual checkups, sick visits, and preventive care</p>
        </div>
      </a>
      <a href="#" class="specialty-card" data-specialty="Dentist">
        <div class="specialty-icon dentist"><i class="ri-emotion-line"></i></div>
        <div>
          <h3>Dentist</h3>
          <p>Cleanings, fillings, and oral health exams</p>
        </div>
      </a>
      <a href="#" class="specialty-card" data-specialty="Dermatologist">
        <div class="specialty-icon derma"><i class="ri-hand-heart-line"></i></div>
        <div>
          <h3>Dermatologist</h3>
          <p>Skin conditions, acne, and cosmetic consultations</p>
        </div>
      </a>
      <a href="#" class="specialty-card" data-specialty="Psychiatrist">
        <div class="specialty-icon psych"><i class="ri-mental-health-line"></i></div>
        <div>
          <h3>Psychiatrist</h3>
          <p>Mental health evaluations and medication management</p>
        </div>
      </a>
      <a href="#" class="specialty-card" data-specialty="Eye Doctor">
        <div class="specialty-icon eye"><i class="ri-eye-line"></i></div>
        <div>
          <h3>Eye Doctor</h3>
          <p>Vision exams, glasses prescriptions, and eye health</p>
        </div>
      </a>
      <a href="#" class="specialty-card" data-specialty="Orthopedic Surgeon">
        <div class="specialty-icon ortho"><i class="ri-body-scan-line"></i></div>
        <div>
          <h3>Orthopedic Surgeon</h3>
          <p>Joint pain, fractures, and sports injuries</p>
        </div>
      </a>
    </div>
  </div>
</section>

<!-- ── HOW IT WORKS ── -->
<section class="how-it-works" id="how-it-works">
  <div class="section-inner" style="text-align:center">
    <span class="section-label"><i class="ri-route-line"></i> How it works</span>
    <h2 class="section-title">Book an appointment in 3 easy steps</h2>
    <p class="section-subtitle" style="margin-left:auto;margin-right:auto">Getting the care you need has never been simpler.</p>
    <div class="steps-grid">
      <div class="step">
        <div class="step-number">1</div>
        <h3>Search for a provider</h3>
        <p>Enter your specialty, condition, or doctor name along with your location and insurance. Browse detailed provider profiles with photos, credentials, and office hours.</p>
      </div>
      <div class="step">
        <div class="step-number">2</div>
        <h3>Choose a time that works for you</h3>
        <p>View real-time availability and pick an appointment slot that fits your schedule — including same-day and next-day options.</p>
      </div>
      <div class="step">
