<script>
(function(){
  // ── Sticky header shadow ──
  const header = document.getElementById('header');
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 10);
  });

  // ── Mobile menu ──
  const hamburger = document.getElementById('hamburgerBtn');
  const drawer = document.getElementById('mobileDrawer');
  const overlay = document.getElementById('drawerOverlay');
  const closeBtn = document.getElementById('drawerClose');

  function openDrawer() {
    drawer.classList.add('open');
    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  }
  function closeDrawer() {
    drawer.classList.remove('open');
    overlay.classList.remove('open');
    document.body.style.overflow = '';
  }
  hamburger.addEventListener('click', openDrawer);
  closeBtn.addEventListener('click', closeDrawer);
  overlay.addEventListener('click', closeDrawer);
  drawer.querySelectorAll('a').forEach(a => a.addEventListener('click', closeDrawer));

  // ── Autocomplete ──
  const searchInput = document.getElementById('searchInput');
  const dropdown = document.getElementById('autocompleteDropdown');

  const suggestions = [
    { icon: 'ri-stethoscope-line', text: 'Primary Care', type: 'Specialty' },
    { icon: 'ri-emotion-line', text: 'Dentist', type: 'Specialty' },
    { icon: 'ri-hand-heart-line', text: 'Dermatologist', type: 'Specialty' },
    { icon: 'ri-mental-health-line', text: 'Psychiatrist', type: 'Specialty' },
    { icon: 'ri-eye-line', text: 'Eye Doctor', type: 'Specialty' },
    { icon: 'ri-body-scan-line', text: 'Orthopedic Surgeon', type: 'Specialty' },
    { icon: 'ri-heart-pulse-line', text: 'Cardiologist', type: 'Specialty' },
    { icon: 'ri-women-line', text: 'OB/GYN', type: 'Specialty' },
    { icon: 'ri-pulse-line', text: 'Back pain', type: 'Condition' },
    { icon: 'ri-headache-line', text: 'Headache / Migraine', type: 'Condition' },
    { icon: 'ri-leaf-line', text: 'Allergies', type: 'Condition' },
    { icon: 'ri-mental-health-line', text: 'Anxiety & Depression', type: 'Condition' },
    { icon: 'ri-user-heart-line', text: 'Dr. Sarah Chen', type: 'Doctor' },
    { icon: 'ri-user-heart-line', text: 'Dr. Michael Rivera', type: 'Doctor' },
    { icon: 'ri-user-heart-line', text: 'Dr. Emily Patel', type: 'Doctor' },
  ];

  let activeIndex = -1;

  function renderDropdown(items) {
    if (!items.length) { dropdown.classList.remove('show'); return; }
    dropdown.innerHTML = items.map((item, i) =>
      `<div class="autocomplete-item${i === activeIndex ? ' active' : ''}" data-index="${i}">
        <i class="${item.icon}"></i>
        <span class="highlight">${item.text}</span>
        <span style="margin-left:auto;font-size:.75rem;color:var(--gray-400)">${item.type}</span>
      </div>`
    ).join('');
    dropdown.classList.add('show');

    dropdown.querySelectorAll('.autocomplete-item').forEach(el => {
      el.addEventListener('mousedown', (e) => {
        e.preventDefault();
        searchInput.value = el.querySelector('.highlight').textContent;
        dropdown.classList.remove('show');
      });
    });
  }

  searchInput.addEventListener('input', () => {
    const q = searchInput.value.trim().toLowerCase();
    activeIndex = -1;
    if (!q) { dropdown.classList.remove('show'); return; }
    const matches = suggestions.filter(s =>
      s.text.toLowerCase().includes(q) || s.type.toLowerCase().includes(q)
    ).slice(0, 6);
    renderDropdown(matches);
  });

  searchInput.addEventListener('keydown', (e) => {
    const items = dropdown.querySelectorAll('.autocomplete-item');
    if (!items.length) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); activeIndex = Math.min(activeIndex + 1, items.length - 1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); activeIndex = Math.max(activeIndex - 1, 0); }
    else if (e.key === 'Enter' && activeIndex >= 0) { e.preventDefault(); searchInput.value = items[activeIndex].querySelector('.highlight').textContent; dropdown.classList.remove('show'); return; }
    else if (e.key === 'Escape') { dropdown.classList.remove('show'); return; }
    else return;
    items.forEach((el, i) => el.classList.toggle('active', i === activeIndex));
  });

  searchInput.addEventListener('blur', () => { dropdown.classList.remove('show'); });
  searchInput.addEventListener('focus', () => { if (searchInput.value.trim()) searchInput.dispatchEvent(new Event('input')); });

  // ── Search form submit ──
  document.getElementById('searchBtn').addEventListener('click', () => {
    const specialty = searchInput.value;
    const location = document.getElementById('locationInput').value;
    const insurance = document.getElementById('insuranceSelect').value;
    if (specialty || location) {
      alert(`Searching for "${specialty || 'all providers'}" in "${location || 'all locations'}"${insurance ? ' with ' + insurance : ''}`);
    }
  });

  // ── Specialty card clicks ──
  document.querySelectorAll('.specialty-card').forEach(card => {
    card.addEventListener('click', (e) => {
      e.preventDefault();
      const specialty = card.dataset.specialty;
      searchInput.value = specialty;
      searchInput.focus();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });

  // ── Geolocation ──
  const locationInput = document.getElementById('locationInput');
  if (navigator.geolocation) {
    const geoBtn = document.createElement('button');
    geoBtn.type = 'button';
    geoBtn.innerHTML = '<i class="ri-crosshair-2-line"></i>';
    geoBtn.style.cssText = 'background:none;border:none;color:var(--gray-400);font-size:1.1rem;cursor:pointer;padding:0;flex-shrink:0';
    geoBtn.title = 'Use my location';
    geoBtn.addEventListener('click', () => {
      navigator.geolocation.getCurrentPosition(
        pos => { locationInput.value = `${pos.coords.latitude.toFixed(2)}, ${pos.coords.longitude.toFixed(2)}`; },
        () => { locationInput.placeholder = 'Location unavailable'; }
      );
    });
    locationInput.parentNode.insertBefore(geoBtn, locationInput.nextSibling);
  }
})();
</script>
